def settle_past_cash(apps, schema_editor):
    """
    Cash tracking starts today. COD cash crew collected on earlier days was handed in the old way
    (by hand, unrecorded), so it is closed as one handover per crew member instead of showing as owed.
    """
    from django.db.models import Sum
    from django.utils import timezone
    Order = apps.get_model('library', 'Order')
    CashHandover = apps.get_model('library', 'CashHandover')
    past = Order.objects.filter(payment_method='cod', status='Delivered', cash_handover__isnull=True,
                                delivered_by__staff_profile__role='FIELD_CREW',
                                delivered_at__date__lt=timezone.localdate())
    for row in past.order_by().values('delivered_by').annotate(total=Sum('total_price')):
        h = CashHandover.objects.create(crew_id=row['delivered_by'], received_by=None, expected=row['total'],
                                        counted=row['total'], note='Before cash tracking started')
        past.filter(delivered_by_id=row['delivered_by']).update(cash_handover=h)


